// B6 — Determine sentiment + branch
const lookup = $input.item.json;
const fb = $('Edit Fields — Feedback Parse').item.json;
const rating = fb['rating'];

let sentiment = 'Neutral';
let branch = 'unhappy';
if (rating >= 4) { sentiment = 'Positive'; branch = 'happy'; }
else if (rating === 3) { sentiment = 'Mixed'; branch = 'unhappy'; }
else if (rating > 0) { sentiment = 'Negative'; branch = 'unhappy'; }

const stars = '★'.repeat(rating) + '☆'.repeat(5 - rating);

return {
  ...lookup,
  rating,
  sentiment,
  branch,
  stars,
  respondedAt: fb['respondedAt'],
  isHappy: branch === 'happy',
  firstName: (lookup['Customer Name'] || 'there').split(' ')[0]
};

