// B6 v3-003 — Find happy customers due for a referral ask (header-whitespace safe)
const trimKeys = (r) => { const out = {}; for (const [k, v] of Object.entries(r || {})) out[k.trim()] = v; return out; };
const rows = $input.all().map(i => trimKeys(i.json));
const setup = $('Edit Fields — Referral Scanner Setup').item.json;
const now = new Date(setup['nowIso']);

const candidates = [];
for (const r of rows) {
  if (!r['Check ID']) continue;
  const rating = parseInt(r['Rating'] || '0');
  if (rating < 4) continue;
  if (r['Public Review Sent'] !== 'Yes') continue;
  if (r['Referral Triggered'] === 'Yes') continue;
  const sentAtStr = r['Public Review Sent At'] || r['Triggered At'];
  if (!sentAtStr) continue;
  const sentAt = new Date(sentAtStr);
  if (isNaN(sentAt.getTime())) continue;
  const hoursSinceSent = (now - sentAt) / (1000 * 60 * 60);
  // Fire 24h+ after the Google review request, skip if >14 days stale
  if (hoursSinceSent < 24) continue;
  if (hoursSinceSent > 14 * 24) continue;
  if (!r['Customer Email']) continue;
  if (!r['Customer Name']) continue;
  candidates.push({
    checkId: r['Check ID'],
    customerName: r['Customer Name'],
    customerEmail: r['Customer Email'],
    businessName: r['Business Name'] || 'Your Business',
    ownerEmail: r['Owner Email'] || 'ndumisoseth12@gmail.com',
    productService: r['Product Service'] || '',
    rating,
    sentAt: sentAtStr,
    hoursSinceSent: Math.round(hoursSinceSent),
    scanId: setup['scanId'],
    nowIso: setup['nowIso']
  });
}
return candidates.map(c => ({ json: c }));

